package com.example.battleshipgame.views;
import android.app.AlertDialog;import android.os.*;import android.view.Gravity;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.battleshipgame.ai.BattleshipAI;import com.example.battleshipgame.customview.BattleshipBoardView;import com.example.battleshipgame.logic.*;import com.example.battleshipgame.ui.Ui;
public class GameActivity extends AppCompatActivity {private GameEngine engine;private final BattleshipAI ai=new BattleshipAI();private BattleshipBoardView enemy,own;private TextView status,points;private int turns;@Override public void onCreate(Bundle state){super.onCreate(state);Board placed=(Board)getIntent().getSerializableExtra("board");engine=placed==null?new GameEngine():new GameEngine(placed);LinearLayout page=Ui.page(this);page.setGravity(Gravity.CENTER_HORIZONTAL);TextView eyebrow=Ui.text(this,"LIVE BATTLE  •  SECTOR 07",11,Ui.CYAN);eyebrow.setLetterSpacing(.12f);Ui.spaced(page,eyebrow,0);status=Ui.text(this,"תורך — בחר משבצת בלוח האויב",16,Ui.INK);status.setTypeface(null,1);Ui.spaced(page,status,4);points=Ui.text(this,"◆ 0 נקודות פגיעה    ◉ מכ״ם: 2",13,Ui.MUTED);Ui.spaced(page,points,2);Ui.spaced(page,Ui.text(this,"מפת האויב",14,Ui.CYAN),9);enemy=new BattleshipBoardView(this);enemy.setBoard(engine.computer,false);enemy.setOnCellClick(this::playerShot);page.addView(enemy,new LinearLayout.LayoutParams(-1,0,1));Ui.spaced(page,Ui.text(this,"הצי שלך",14,Ui.CYAN),8);own=new BattleshipBoardView(this);own.setBoard(engine.player,true);page.addView(own,new LinearLayout.LayoutParams(-1,0,1));Button radar=Ui.button(this,"◉  הפעל מכ״ם 2×2  •  2 נקודות",false);radar.setOnClickListener(v->radar());Ui.spaced(page,radar,10);setContentView(page);}private void playerShot(int r,int c){ShotResult x=engine.playerShot(r,c);if(x==ShotResult.ALREADY_SHOT){status.setText("המשבצת כבר נבדקה");return;}turns++;enemy.invalidate();update(x==ShotResult.MISS?"החטאה — המחשב חושב…":"פגיעה מדויקת!");if(engine.isOver()){finishGame(true);return;}if(x==ShotResult.MISS){enemy.setBoardEnabled(false);new Handler().postDelayed(this::computerTurn,700);}}private void computerTurn(){int[] p=ai.choose(engine.player);ShotResult x=engine.computerShot(p[0],p[1]);ai.learn(p[0],p[1],x);own.invalidate();if(engine.isOver()){finishGame(false);return;}if(x==ShotResult.MISS){enemy.setBoardEnabled(true);update("תורך — המחשב החטיא");}else{update("פגיעה של המחשב — הוא יורה שוב");new Handler().postDelayed(this::computerTurn,700);}}private void radar(){if(!engine.powers.spend(2)){Toast.makeText(this,"נדרשות 2 נקודות פגיעה",Toast.LENGTH_SHORT).show();return;}enemy.setBoard(engine.computer,true);status.setText("המכ״ם חושף מטרות לרגע");new Handler().postDelayed(()->enemy.setBoard(engine.computer,false),1200);update("");}private void update(String m){if(!m.isEmpty())status.setText(m);points.setText("◆ "+engine.powers.getPoints()+" נקודות פגיעה    ◉ מכ״ם: 2");}private void finishGame(boolean won){getSharedPreferences("history",0).edit().putString("last",(won?"ניצחון":"הפסד")+" • "+turns+" תורות").apply();new AlertDialog.Builder(this).setTitle(won?"ניצחת בקרב!":"הקרב הסתיים").setMessage("מספר תורות: "+turns).setPositiveButton("לתפריט",(d,w)->finish()).show();}}
